/* global figma */
// GENERATED by scripts/figma/build-plugin.cjs from design/tokens.json + design.pen(home) — 직접 수정하지 말고 `pnpm figma:build`를 실행한다.
// Figma 데스크톱 앱: Plugins → Development → Import plugin from manifest… → scripts/figma/manifest.json → 실행.
const TOKENS = __TOKENS__;
const ICONS = __ICONS__;
const FONT_CANDIDATES = ["Pretendard", "Noto Sans KR", "Inter"];
const WEIGHT_STYLES = { 400: ["Regular"], 500: ["Medium"], 600: ["SemiBold", "Semi Bold"], 700: ["Bold"] };
const SHADOW_CARD = { type: "DROP_SHADOW", color: { r: 0x36 / 255, g: 0x29 / 255, b: 0xb7 / 255, a: 0.07 }, offset: { x: 0, y: 4 }, radius: 30, spread: 0, visible: true, blendMode: "NORMAL" };

let fontFamily = "Inter";
let mode = "light";
const loadedFonts = new Map();
const colorVars = { light: {}, dark: {} };
const textStyles = {};

function hexToRgb(hex) {
  const n = parseInt(hex.replace("#", "").slice(0, 6), 16);
  return { r: ((n >> 16) & 255) / 255, g: ((n >> 8) & 255) / 255, b: (n & 255) / 255 };
}

function solid(hex, opacity) {
  const paint = { type: "SOLID", color: hexToRgb(hex) };
  if (opacity !== undefined) paint.opacity = opacity;
  return paint;
}

function colorPaint(name, opacity) {
  const hex = TOKENS.colors[mode][name];
  if (!hex) throw new Error(`알 수 없는 색 토큰: ${name}`);
  let paint = solid(hex, opacity);
  const variable = colorVars[mode][name];
  if (variable) {
    try {
      paint = figma.variables.setBoundVariableForPaint(paint, "color", variable);
    } catch (error) {
      console.warn("변수 바인딩 실패", name, error);
    }
  }
  return paint;
}

async function pickFontFamily() {
  const fonts = await figma.listAvailableFontsAsync();
  const families = new Set(fonts.map((f) => f.fontName.family));
  return FONT_CANDIDATES.find((c) => families.has(c)) || "Inter";
}

async function font(weight) {
  const key = String(weight);
  if (loadedFonts.has(key)) return loadedFonts.get(key);
  for (const style of [...WEIGHT_STYLES[key], "Regular"]) {
    const name = { family: fontFamily, style };
    try {
      await figma.loadFontAsync(name);
      loadedFonts.set(key, name);
      return name;
    } catch (error) {
      continue;
    }
  }
  throw new Error(`${fontFamily} 서체를 불러올 수 없습니다`);
}

function frame(name, o = {}) {
  const f = figma.createFrame();
  f.name = name;
  f.fills = o.fill ? [colorPaint(o.fill, o.fillOpacity)] : [];
  f.clipsContent = o.clip === true;
  if (o.layout) {
    f.layoutMode = o.layout;
    f.primaryAxisSizingMode = "AUTO";
    f.counterAxisSizingMode = "AUTO";
    f.itemSpacing = o.gap || 0;
    const p = o.padding || [0, 0, 0, 0];
    f.paddingTop = p[0];
    f.paddingRight = p[1];
    f.paddingBottom = p[2];
    f.paddingLeft = p[3];
    if (o.justify) f.primaryAxisAlignItems = o.justify;
    if (o.align) f.counterAxisAlignItems = o.align;
  }
  if (o.radius !== undefined) f.cornerRadius = o.radius;
  if (o.radii) {
    f.topLeftRadius = o.radii[0];
    f.topRightRadius = o.radii[1];
    f.bottomRightRadius = o.radii[2];
    f.bottomLeftRadius = o.radii[3];
  }
  if (o.stroke) {
    f.strokes = [colorPaint(o.stroke)];
    f.strokeWeight = o.strokeWeight || 1;
  }
  if (o.effect) f.effects = [o.effect];
  if (o.opacity !== undefined) f.opacity = o.opacity;
  return f;
}

function add(parent, node, o = {}) {
  parent.appendChild(node);
  const canHug = node.type === "TEXT" || (node.layoutMode !== undefined && node.layoutMode !== "NONE");
  const w = o.w === undefined ? "HUG" : o.w;
  const h = o.h === undefined ? "HUG" : o.h;
  if (typeof w === "number") {
    node.resize(w, node.height);
    node.layoutSizingHorizontal = "FIXED";
  } else if (w === "FILL" || canHug) {
    node.layoutSizingHorizontal = w;
  }
  if (typeof h === "number") {
    node.resize(node.width, h);
    node.layoutSizingVertical = "FIXED";
  } else if (h === "FILL" || canHug) {
    node.layoutSizingVertical = h;
  }
  return node;
}

async function text(content, tokenName, colorName, o = {}) {
  const ty = TOKENS.typography[tokenName];
  if (!ty) throw new Error(`알 수 없는 타이포 토큰: ${tokenName}`);
  const t = figma.createText();
  t.name = o.name || content;
  t.fontName = await font(ty.fontWeight);
  t.characters = content;
  t.fontSize = ty.fontSize;
  t.lineHeight = { value: ty.lineHeight, unit: "PIXELS" };
  t.letterSpacing = { value: ty.letterSpacing, unit: "PIXELS" };
  t.fills = [colorPaint(colorName, o.opacity)];
  if (o.align) t.textAlignHorizontal = o.align;
  t.textAutoResize = "WIDTH_AND_HEIGHT";
  const style = textStyles[tokenName];
  if (style) {
    try {
      await t.setTextStyleIdAsync(style.id);
    } catch (error) {
      t.textStyleId = style.id;
    }
  }
  return t;
}

async function textFill(parent, content, tokenName, colorName, o = {}) {
  const t = await text(content, tokenName, colorName, o);
  parent.appendChild(t);
  t.textAutoResize = "HEIGHT";
  t.layoutSizingHorizontal = "FILL";
  return t;
}

function icon(name, size, colorName) {
  const svg = ICONS[name];
  if (!svg) throw new Error(`알 수 없는 아이콘: ${name}`);
  const node = figma.createNodeFromSvg(
    svg.replace(/currentColor/g, TOKENS.colors[mode][colorName]).replace(/__SIZE__/g, String(size))
  );
  node.name = `icon: ${name}`;
  return node;
}

// ---------- Variables · Styles ----------
function createColorCollection() {
  const collection = figma.variables.createVariableCollection("color");
  const lightId = collection.modes[0].modeId;
  collection.renameMode(lightId, "light");
  let darkId = null;
  let darkCollection = null;
  try {
    darkId = collection.addMode("dark");
  } catch (error) {
    darkCollection = figma.variables.createVariableCollection("color/dark");
    darkCollection.renameMode(darkCollection.modes[0].modeId, "dark");
    figma.notify("이 플랜은 컬렉션당 모드 1개라 다크 값을 별도 컬렉션 color/dark에 만듭니다", { timeout: 4000 });
  }
  for (const name of Object.keys(TOKENS.colors.light)) {
    const v = figma.variables.createVariable(name, collection, "COLOR");
    v.setValueForMode(lightId, { ...hexToRgb(TOKENS.colors.light[name]), a: 1 });
    colorVars.light[name] = v;
    if (darkId) {
      v.setValueForMode(darkId, { ...hexToRgb(TOKENS.colors.dark[name]), a: 1 });
      colorVars.dark[name] = v;
    } else {
      const d = figma.variables.createVariable(name, darkCollection, "COLOR");
      d.setValueForMode(darkCollection.modes[0].modeId, { ...hexToRgb(TOKENS.colors.dark[name]), a: 1 });
      colorVars.dark[name] = d;
    }
  }
  return { collection, darkId, darkCollection };
}

function createFloatCollection(name, values) {
  const collection = figma.variables.createVariableCollection(name);
  const modeId = collection.modes[0].modeId;
  for (const [key, value] of Object.entries(values)) {
    const v = figma.variables.createVariable(key, collection, "FLOAT");
    v.setValueForMode(modeId, value);
  }
}

function createPaintStyles() {
  for (const m of ["light", "dark"]) {
    for (const [name, hex] of Object.entries(TOKENS.colors[m])) {
      const style = figma.createPaintStyle();
      style.name = `color/${m}/${name}`;
      style.paints = [solid(hex)];
    }
  }
}

async function createTextStyles() {
  for (const [name, ty] of Object.entries(TOKENS.typography)) {
    const style = figma.createTextStyle();
    style.name = `text/${name}`;
    style.fontName = await font(ty.fontWeight);
    style.fontSize = ty.fontSize;
    style.lineHeight = { value: ty.lineHeight, unit: "PIXELS" };
    style.letterSpacing = { value: ty.letterSpacing, unit: "PIXELS" };
    textStyles[name] = style;
  }
}

// ---------- Foundations 프레임 ----------
const COLOR_GROUPS = {
  SURFACE: ["background", "foreground", "card", "card-foreground", "popover", "popover-foreground", "border", "input", "ring"],
  BRAND: ["primary", "primary-foreground", "secondary", "secondary-foreground", "accent", "accent-foreground", "muted", "muted-foreground", "inverse", "inverse-foreground"],
  SEMANTIC: ["destructive", "destructive-foreground", "destructive-muted", "positive", "positive-foreground", "positive-muted", "warning", "warning-foreground", "warning-muted"],
  "SEMANTIC 2 / FIXED": ["info", "info-foreground", "info-muted", "highlight", "highlight-foreground", "white", "black"],
};

async function buildColorStyleFrame() {
  const root = frame("Color style / tokens", { layout: "VERTICAL", gap: 24, padding: [32, 32, 32, 32], fill: "white", radius: 16 });
  add(root, await text("Color style / tokens — design/tokens.json semantic.color", "h1", "foreground"));
  for (const m of ["light", "dark"]) {
    mode = m;
    const section = add(root, frame(`Mode / ${m}`, { layout: "VERTICAL", gap: 16, padding: [24, 24, 24, 24], fill: "background", radius: 15, stroke: "border" }));
    add(section, await text(m.toUpperCase(), "h3", "foreground"));
    for (const [group, names] of Object.entries(COLOR_GROUPS)) {
      add(section, await text(group, "caption", "muted-foreground"));
      const row = add(section, frame(`Row ${group}`, { layout: "HORIZONTAL", gap: 12 }));
      for (const name of names) {
        const swatch = add(row, frame(name, { layout: "VERTICAL", gap: 6 }), { w: 104 });
        add(swatch, frame("swatch", { fill: name, radius: 10, stroke: "border" }), { w: "FILL", h: 56 });
        await textFill(swatch, name, "caption", "foreground");
      }
    }
  }
  mode = "light";
  return root;
}

async function buildTextStyleFrame() {
  const root = frame("Text style / tokens", { layout: "VERTICAL", gap: 20, padding: [32, 32, 32, 32], fill: "background", radius: 16 });
  root.resize(900, root.height);
  root.counterAxisSizingMode = "FIXED";
  add(root, await text("Text style / tokens — design/tokens.json semantic.typography", "h1", "foreground"));
  const samples = TOKENS.samples;
  for (const [name, ty] of Object.entries(TOKENS.typography)) {
    const row = add(root, frame(`Row ${name}`, { layout: "HORIZONTAL", gap: 24, align: "CENTER", padding: [12, 0, 12, 0] }), { w: "FILL" });
    const meta = add(row, frame("Meta", { layout: "VERTICAL", gap: 4 }), { w: 160 });
    add(meta, await text(`text-${name}`, "label", "primary"));
    add(meta, await text(`${ty.fontSize}/${ty.lineHeight} · ${ty.fontWeight} · ${ty.letterSpacing}`, "caption", "muted-foreground"));
    await textFill(row, samples[name] || name, name, "foreground");
  }
  return root;
}

// ---------- home ----------
const QUICK_MENU = [
  ["wallet", "계좌·카드", "primary"], ["arrow-left-right", "이체", "destructive"], ["banknote", "출금", "info"],
  ["smartphone", "휴대폰 충전", "warning"], ["receipt", "공과금", "positive"], ["piggy-bank", "저축", "primary"],
  ["credit-card", "신용카드", "highlight"], ["chart-column", "거래 내역", "primary"], ["users", "받는 사람", "destructive"],
];

async function buildHome(name) {
  const home = frame(name, { layout: "VERTICAL", fill: "background", clip: true });
  home.resize(390, 844);
  home.primaryAxisSizingMode = "FIXED";
  home.counterAxisSizingMode = "FIXED";

  const header = add(home, frame("Header", { layout: "HORIZONTAL", gap: 16, align: "CENTER", padding: [75, 24, 24, 24], fill: "primary" }), { w: "FILL" });
  const avatar = add(header, frame("Avatar", { layout: "VERTICAL", justify: "CENTER", align: "CENTER", fill: "white", radius: 25 }), { w: 50, h: 50 });
  add(avatar, icon("user", 26, "primary"));
  await textFill(header, "안녕하세요, 김재영님", "h3", "primary-foreground", { name: "Greeting" });
  const bell = add(header, frame("Notification button", { layout: "VERTICAL", justify: "CENTER", align: "CENTER" }), { w: 44, h: 44 });
  add(bell, icon("bell", 24, "primary-foreground"));
  const badge = add(bell, frame("Badge", { layout: "HORIZONTAL", justify: "CENTER", align: "CENTER", padding: [0, 5, 0, 5], fill: "destructive", radius: 8 }));
  add(badge, await text("3", "caption", "destructive-foreground", { name: "count" }));
  badge.layoutPositioning = "ABSOLUTE";
  badge.x = 26;
  badge.y = 4;

  const body = add(home, frame("Body", { layout: "VERTICAL", gap: 32, padding: [24, 24, 24, 24], fill: "background" }), { w: "FILL", h: "FILL" });

  const stack = add(body, frame("AccountCard / stack", { layout: "VERTICAL" }), { w: "FILL" });
  const card = add(stack, frame("AccountCard / default", { layout: "VERTICAL", gap: 24, padding: [20, 20, 20, 20], fill: "primary", radius: 15 }), { w: "FILL" });
  const top = add(card, frame("Top row", { layout: "HORIZONTAL", justify: "SPACE_BETWEEN", align: "MIN" }), { w: "FILL" });
  const titles = add(top, frame("Titles", { layout: "VERTICAL", gap: 4 }));
  add(titles, await text("생활비 통장", "h2", "primary-foreground", { name: "alias" }));
  add(titles, await text("하네스은행", "body-sm", "primary-foreground", { name: "bank", opacity: 0.8 }));
  const toggle = add(top, frame("Toggle balance", { layout: "VERTICAL", justify: "CENTER", align: "CENTER" }), { w: 44, h: 44 });
  add(toggle, icon("eye", 22, "primary-foreground"));
  const amountRow = add(card, frame("Amount row", { layout: "VERTICAL", gap: 4 }));
  add(amountRow, await text("110-***-**6789", "body", "primary-foreground", { name: "masked account", opacity: 0.9 }));
  add(amountRow, await text("3,469,520원", "amount-md", "primary-foreground", { name: "AmountText / md" }));
  const peek1 = add(stack, frame("Stack peek 1", { layout: "HORIZONTAL", padding: [0, 20, 0, 20] }), { w: "FILL" });
  add(peek1, frame("peek destructive", { fill: "destructive", radii: [0, 0, 15, 15] }), { w: "FILL", h: 8 });
  const peek2 = add(stack, frame("Stack peek 2", { layout: "HORIZONTAL", padding: [0, 32, 0, 32] }), { w: "FILL" });
  add(peek2, frame("peek primary/60", { fill: "primary", radii: [0, 0, 15, 15], opacity: 0.6 }), { w: "FILL", h: 8 });

  const grid = add(body, frame("QuickMenu", { layout: "VERTICAL", gap: 16 }), { w: "FILL" });
  for (let r = 0; r < 3; r++) {
    const row = add(grid, frame(`Row ${r + 1}`, { layout: "HORIZONTAL", gap: 16 }), { w: "FILL" });
    for (const [iconName, label, color] of QUICK_MENU.slice(r * 3, r * 3 + 3)) {
      const tile = add(row, frame(`Tile / ${label}`, { layout: "VERTICAL", gap: 8, justify: "CENTER", align: "CENTER", padding: [12, 12, 12, 12], fill: "card", radius: 15, effect: SHADOW_CARD }), { w: "FILL", h: 96 });
      add(tile, icon(iconName, 28, color));
      await textFill(tile, label, "label", "muted-foreground", { align: "CENTER" });
    }
  }

  const tabBar = add(home, frame("TabBar", { layout: "HORIZONTAL", justify: "SPACE_BETWEEN", align: "CENTER", padding: [20, 40, 34, 40], fill: "card" }), { w: "FILL" });
  const pill = add(tabBar, frame("Tab / home / active", { layout: "HORIZONTAL", gap: 8, align: "CENTER", padding: [0, 16, 0, 16], fill: "primary", radius: 18 }), { h: 36 });
  add(pill, icon("house", 20, "primary-foreground"));
  add(pill, await text("홈", "caption", "primary-foreground", { name: "label" }));
  for (const [iconName, label] of [["search", "검색"], ["mail", "메시지"], ["settings", "설정"]]) {
    const tab = add(tabBar, frame(`Tab / ${label}`, { layout: "VERTICAL", justify: "CENTER", align: "CENTER" }), { w: 44, h: 36 });
    add(tab, icon(iconName, 24, "muted-foreground"));
  }
  return home;
}

// ---------- 실행 ----------
async function getOrCreatePage(name) {
  await figma.loadAllPagesAsync();
  let page = figma.root.children.find((p) => p.name === name);
  if (!page) {
    page = figma.createPage();
    page.name = name;
  }
  return page;
}

async function main() {
  fontFamily = await pickFontFamily();
  await font(400);
  const { collection, darkId } = createColorCollection();
  createFloatCollection("radius", TOKENS.radius);
  createFloatCollection("size", TOKENS.size);
  createPaintStyles();
  await createTextStyles();

  const foundations = await getOrCreatePage("Foundations");
  const colorFrame = await buildColorStyleFrame();
  foundations.appendChild(colorFrame);
  colorFrame.x = 0;
  colorFrame.y = 0;
  const textFrame = await buildTextStyleFrame();
  foundations.appendChild(textFrame);
  textFrame.x = 0;
  textFrame.y = colorFrame.height + 120;

  const screens = await getOrCreatePage("Screens");
  mode = "light";
  const home = await buildHome("home");
  screens.appendChild(home);
  home.x = 0;
  home.y = 0;
  mode = "dark";
  const homeDark = await buildHome("home/dark");
  screens.appendChild(homeDark);
  homeDark.x = 470;
  homeDark.y = 0;
  if (darkId) {
    try {
      homeDark.setExplicitVariableModeForCollection(collection, darkId);
    } catch (error) {
      console.warn("다크 모드 지정 실패", error);
    }
  }
  mode = "light";

  await figma.setCurrentPageAsync(screens);
  figma.viewport.scrollAndZoomIntoView([home, homeDark]);
  figma.notify(`가져오기 완료 — 서체 ${fontFamily}, 변수 ${Object.keys(TOKENS.colors.light).length}색 · Foundations/Screens 페이지`);
}

main()
  .then(() => figma.closePlugin())
  .catch((error) => {
    console.error(error);
    figma.closePlugin(`가져오기 실패: ${error.message}`);
  });
